            if (FormLinkInformation.TryFactory(obj.Script, out var ScriptInfo))
            {
                yield return ScriptInfo;
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks())
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.LoopingSound, out var LoopingSoundInfo))
            {
                yield return LoopingSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.PasswordNote, out var PasswordNoteInfo))
            {
                yield return PasswordNoteInfo;
            }
            foreach (var item in obj.MenuItems.SelectMany(f => f.EnumerateFormLinks()))
            {
                yield return FormLinkInformation.Factory(item);
            }
            yield break;
        }
        
